(() => {
  const column = (slot) => {
    const outlet = document.querySelector('[data-slot="' + slot + '"]')
    return outlet === null ? null : outlet.parentElement
  }
  const left = column('sidebar')
  const main = column('main')
  const right = column('rightbar')
  if (left === null || main === null || right === null) return 'MISSING COLUMN'
  const leftBg = getComputedStyle(left, '::before').backgroundImage
  const mainBg = getComputedStyle(main, '::after').backgroundImage
  const rightBg = getComputedStyle(right, '::after').backgroundImage
  return leftBg.includes('rgb(250, 250, 250)') && mainBg === 'none' && rightBg.includes('0.55')
})()
